"""Workspace access management: LLOs, the Users list (replacing testers), and
the record of who has had a role.

Each ``WorkspaceTester`` row is carried over as a Network Manager ``WorkspaceUser``
entry for the tester's email and team. No LLO is created for a tester's team:
an LLO lets in every member of that Connect organisation, which nobody chose."""

import django.db.models.deletion
import django.utils.timezone
from django.conf import settings
from django.db import migrations, models


def testers_to_users(apps, schema_editor):
    Tester = apps.get_model("labs", "WorkspaceTester")
    WorkspaceUser = apps.get_model("labs", "WorkspaceUser")
    for t in Tester.objects.select_related("user").order_by("pk"):
        email = (t.user.email or t.user.username or "").strip().lower()
        if not email:
            continue
        WorkspaceUser.objects.get_or_create(
            workspace_id=t.workspace_id,
            email=email,
            defaults={
                "user_id": t.user_id,
                "role": "network_manager",
                "team": t.team,
                "added_by_id": t.added_by_id,
            },
        )


def users_to_testers(apps, schema_editor):
    Tester = apps.get_model("labs", "WorkspaceTester")
    WorkspaceUser = apps.get_model("labs", "WorkspaceUser")
    for u in WorkspaceUser.objects.filter(role="network_manager", user__isnull=False).exclude(team="").order_by("pk"):
        Tester.objects.get_or_create(
            workspace_id=u.workspace_id, user_id=u.user_id, defaults={"team": u.team, "added_by_id": u.added_by_id}
        )


